  'update',
  $payload${"moduleId":"nerve-conduction","revisionType":"quiz","title":"Evaluación: N. Cutáneo lateral del antebrazo (musculocutáneo)","quizTopicId":"lateral-cutaneous-forearm","passScore":70,"maxAttempts":null,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"lac-q1","sortOrder":0,"type":"single","difficulty":"basic","stem":"¿De qué nervio y de qué raíces es el cutáneo lateral del antebrazo, y para qué lo usa la lección?","options":[{"id":"lac-q1-a","text":"Es la rama sensitiva terminal del musculocutáneo, C5–C6, y separa plexo del tronco superior de radiculopatía.","isCorrect":true},{"id":"lac-q1-b","text":"Es rama del mediano, C8–T1, y diagnostica Guyon.","isCorrect":false},{"id":"lac-q1-c","text":"Es el radial superficial, y su caída significa Wartenberg.","isCorrect":false},{"id":"lac-q1-d","text":"Es un nervio motor puro del bíceps.","isCorrect":false}],"explanation":"Inerva la cara lateral del antebrazo. En el tronco superior o en el musculocutáneo el SNAP baja; en la radiculopatía C5–C6 se conserva.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"lac-q2","sortOrder":1,"type":"image_choice","difficulty":"intermediate","stem":"El potencial de la figura necesitó unos 25 promedios para verse a 10 µV/div. En el protocolo ortodrómico de esta lección, ¿dónde van G1 y el estímulo?","options":[{"id":"lac-q2-a","text":"G1 2 cm lateral al tendón del bíceps en el pliegue del codo; estímulo 12 cm distal; 20–30 promedios.","isCorrect":true},{"id":"lac-q2-b","text":"G1 en la tabaquera y estímulo 10 cm proximal, sin promediar.","isCorrect":false},{"id":"lac-q2-c","text":"G1 en el dedo 5 y estímulo en Guyon.","isCorrect":false},{"id":"lac-q2-d","text":"G1 detrás del maléolo lateral, a 14 cm.","isCorrect":false}],"explanation":"G2 queda 3–4 cm proximal a G1. A 12 cm el pico normal es 2.4–2.9 ms (anormal >3.2), la amplitud 10–25 µV (anormal <5) y la velocidad 55–70 m/s. El potencial es pequeño: por eso 20–30 promedios.\n\n📚 Referencia: Buschbacher RM, Kumbhare D, Robinson L. Buschbacher's Manual of Nerve Conduction Studies (3rd ed). Demos Medical (2015).","citations":[{"authors":"Buschbacher RM, Kumbhare D, Robinson L","title":"Buschbacher's Manual of Nerve Conduction Studies (3rd ed)","journal":"Demos Medical","year":2015}],"imageUrl":"/quiz-traces/lateral-cutaneous-forearm-lac-q2.svg","imageAlt":"SNAP pequeño, cerca de 12 µV, inicio alrededor de 2.6 ms, a 1 ms/div y 10 µV/div."},{"id":"lac-q3","sortOrder":2,"type":"single","difficulty":"advanced","stem":"Dolor C5–C6, bíceps débil. SNAP cutáneo lateral del antebrazo normal y SNAP radial también normal. ¿Qué localización favorece la lección?","options":[{"id":"lac-q3-a","text":"Radiculopatía C5–C6: el ganglio está intacto y el SNAP se conserva.","isCorrect":true},{"id":"lac-q3-b","text":"Plexopatía del tronco superior, que también conserva este SNAP.","isCorrect":false},{"id":"lac-q3-c","text":"Corte del musculocutáneo en el brazo.","isCorrect":false},{"id":"lac-q3-d","text":"Parsonage-Turner con seguridad, porque ese SNAP siempre está normal en esa enfermedad.","isCorrect":false}],"explanation":"La perla usa este SNAP para separar raíz (normal) de plexo superior (bajo). Es más limpio que el radial para C5–C6, porque el radial trae C7. En Parsonage-Turner la lección dice que este SNAP puede estar reducido, no que siempre esté normal.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"lac-q4","sortOrder":3,"type":"single","difficulty":"intermediate","stem":"¿Por qué la lección prefiere este SNAP al radial cuando la pregunta es C5–C6?","options":[{"id":"lac-q4-a","text":"El radial recibe C7, así que un radial normal no limpia tan bien el tronco superior.","isCorrect":true},{"id":"lac-q4-b","text":"El radial no tiene fibras sensitivas.","isCorrect":false},{"id":"lac-q4-c","text":"Este potencial es más grande que el radial y no necesita promedio.","isCorrect":false},{"id":"lac-q4-d","text":"El cutáneo lateral cruza el codo y por eso detecta la neuropatía ulnar.","isCorrect":false}],"explanation":"La perla lo dice así: más confiable que el radial para C5–C6 por la contribución C7 del radial. El potencial, además, es pequeño y sí se promedia.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}]}],"examQuestions":[{"module_id":"nerve-conduction","topic_id":"lateral-cutaneous-forearm","topic_name":"N. Cutáneo lateral del antebrazo (musculocutáneo)","island_name":"EMG","stem":"Hombre de 52 años, debilidad de bíceps y deltoides derechos, dolor de hombro. SNAP cutáneo lateral del antebrazo 4 µV (contralateral 18 µV). Radial sensitivo normal. No hay trauma cutáneo en el antebrazo.","difficulty":3,"is_critical":true,"findings":[{"type":"AMPL","label":"Cutáneo lateral del antebrazo","value":"4 µV frente a 18 µV"},{"type":"SIGN","label":"Clínica","value":"Bíceps y deltoides débiles"}],"options":[{"text":"Lesión postganglionar C5–C6: plexo superior o musculocutáneo, no una raíz pura.","is_correct":true,"feedback":"4 µV está bajo el límite de 5 µV y la asimetría supera el 50 %. En la radiculopatía este SNAP seguiría normal."},{"text":"Radiculopatía C5–C6 típica.","is_correct":false,"feedback":"La raíz preserva el SNAP."},{"text":"Wartenberg, por el radial normal.","is_correct":false,"feedback":"Wartenberg tumba el radial sensitivo, que aquí está normal."},{"text":"Estudio normal: 4 µV entra en 10–25 µV.","is_correct":false,"feedback":"10–25 µV es lo normal; por debajo de 5 µV es el límite, y el otro lado está en 18 µV."}],"pearl":"Cutáneo lateral bajo: plexo superior o musculocutáneo. El mismo SNAP normal, con clínica C5–C6: raíz.","source_reference":"Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","tags":["nerve-conduction","lateral-cutaneous-forearm"],"status":"DRAFT"}]}$payload$::jsonb,
